// Single source of truth for cue tags. Parser, router, prompts and effects import from here.

export const STYLES = ["whisper", "slow", "trembling", "shout"] as const;
export type StyleTag = (typeof STYLES)[number];
export type Style = "normal" | StyleTag;

export const NONVERBALS = ["breath", "sigh", "gasp", "laugh"] as const;
export type NonVerbal = (typeof NONVERBALS)[number];

export const SFX_NAMES = [
  "creak",
  "knock",
  "footsteps",
  "door",
  "heartbeat",
  "static",
  "drip",
  "scrape",
  "whispers",
] as const;
export type SfxName = (typeof SFX_NAMES)[number];

export const LIGHT_MODES = ["flicker", "blackout", "red", "pulse", "calm"] as const;
export type LightMode = (typeof LIGHT_MODES)[number];

export const AMBIENT_MODES = ["low", "swell", "stop"] as const;
export type AmbientMode = (typeof AMBIENT_MODES)[number];

/** Tag names (first word inside the brackets). */
export const TAG = {
  pause: "pause",
  sfx: "sfx",
  light: "light",
  ambient: "ambient",
  photo: "photo",
} as const;

export const PHOTO_VERB = "reveal";

/** [pause N] is clamped to this range (seconds). */
export const PAUSE_MIN = 0.2;
export const PAUSE_MAX = 6;
/** Used when [pause] has a missing or unparsable argument. */
export const PAUSE_DEFAULT = 1;

/** [light blackout N]: same clamp as pause, default when N is missing/bad. */
export const BLACKOUT_MIN = PAUSE_MIN;
export const BLACKOUT_MAX = PAUSE_MAX;
export const BLACKOUT_DEFAULT = 2;

export type CueEvent =
  | { kind: "speech"; text: string; style: Style }
  | { kind: "nonverbal"; nv: NonVerbal }
  | { kind: "pause"; seconds: number }
  | { kind: "sfx"; name: SfxName }
  | { kind: "light"; mode: LightMode; seconds?: number }
  | { kind: "ambient"; mode: AmbientMode }
  | { kind: "photo"; id: string };

/** Every word that is a recognised tag name; used to recognise stray junk like "(pause 2)". */
export const ALL_TAG_WORDS: readonly string[] = [
  ...Object.values(TAG),
  ...STYLES,
  ...NONVERBALS,
];

export const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

import {
  ALL_TAG_WORDS,
  AMBIENT_MODES,
  BLACKOUT_DEFAULT,
  BLACKOUT_MAX,
  BLACKOUT_MIN,
  LIGHT_MODES,
  NONVERBALS,
  PAUSE_DEFAULT,
  PAUSE_MAX,
  PAUSE_MIN,
  PHOTO_VERB,
  SFX_NAMES,
  STYLES,
  TAG,
  clamp,
  type AmbientMode,
  type CueEvent,
  type LightMode,
  type NonVerbal,
  type SfxName,
  type Style,
  type StyleTag,
} from "./spec";

export interface ParserStats {
  /** Tags dropped because they were unknown or malformed (shown in DebugPanel). */
  unknownTags: number;
  /** Junk spans dropped (e.g. "(pause 2)", "*sighs*", unterminated "[tag"). */
  junkDropped: number;
  /** Tags with a missing/bad argument that fell back to a default. */
  defaulted: number;
}

const includes = <T extends string>(list: readonly T[], v: string): v is T => (list as readonly string[]).includes(v);

// `[ ... ]` tag; `*...*` stage direction; `(word ...)` where word is a tag name.
const TOKEN_RE = new RegExp(
  String.raw`\[([^\[\]]*)\]` + // 1: bracket tag
    String.raw`|\*+([^*\n]{1,40})\*+` + // 2: *junk*
    String.raw`|\(\s*(?:${ALL_TAG_WORDS.join("|")})\b[^()]*\)`, // (pause 2)
  "gi",
);

function parseNumber(s: string | undefined): number | undefined {
  if (s === undefined) return undefined;
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : undefined;
}

/**
 * Incremental cue parser. Feed streamed chunks with push(); events are emitted
 * for each completed line. Call flush() at end of stream for the last line.
 * Never throws: bad input is dropped, logged and counted.
 */
export class CueParser {
  readonly stats: ParserStats = { unknownTags: 0, junkDropped: 0, defaulted: 0 };
  private buf = "";

  constructor(private readonly warn: (msg: string) => void = (m) => console.warn(m)) {}

  push(chunk: string): CueEvent[] {
    this.buf += chunk;
    const lines = this.buf.split(/\r\n|\n|\r/);
    this.buf = lines.pop() ?? "";
    return lines.flatMap((l) => this.parseLine(l));
  }

  flush(): CueEvent[] {
    const rest = this.buf;
    this.buf = "";
    return rest ? this.parseLine(rest) : [];
  }

  /** Convenience: parse a whole script. */
  static parse(text: string, warn?: (msg: string) => void): { events: CueEvent[]; stats: ParserStats } {
    const p = new CueParser(warn);
    const events = [...p.push(text), ...p.flush()];
    return { events, stats: p.stats };
  }

  private drop(what: string, raw: string) {
    this.stats.unknownTags++;
    this.warn(`cue: dropped ${what}: ${raw}`);
  }

  private parseLine(line: string): CueEvent[] {
    const events: CueEvent[] = [];
    let style: Style = "normal"; // style scope is one line; last style tag wins from that point
    let last = 0;

    const speech = (raw: string) => {
      // an unterminated "[tag" with no closing bracket is junk, not speech
      let text = raw;
      const open = text.indexOf("[");
      if (open !== -1) {
        this.stats.junkDropped++;
        this.warn(`cue: dropped unterminated tag: ${text.slice(open)}`);
        text = text.slice(0, open);
      }
      text = text.replace(/\s+/g, " ").trim();
      // nothing pronounceable (punctuation only) is not worth synthesizing
      if (text && /[\p{L}\p{N}]/u.test(text)) events.push({ kind: "speech", text, style });
    };

    for (const m of line.matchAll(TOKEN_RE)) {
      speech(line.slice(last, m.index));
      last = m.index + m[0].length;

      if (m[1] === undefined) {
        this.stats.junkDropped++;
        this.warn(`cue: dropped junk: ${m[0]}`);
        continue;
      }
      const tag = this.parseTag(m[1]);
      if (!tag) {
        this.drop("tag", m[0]);
      } else if ("setStyle" in tag) {
        style = tag.setStyle;
      } else {
        events.push(tag);
      }
    }
    speech(line.slice(last));
    return events;
  }

  private parseTag(inner: string): CueEvent | { setStyle: StyleTag } | null {
    const words = inner.trim().toLowerCase().split(/\s+/).filter(Boolean);
    const [name, ...args] = words;
    if (!name) return null;

    if (includes(STYLES, name)) return { setStyle: name };
    if (includes(NONVERBALS, name)) return { kind: "nonverbal", nv: name as NonVerbal };

    switch (name) {
      case TAG.pause: {
        let n = parseNumber(args[0]);
        if (n === undefined) {
          this.stats.defaulted++;
          this.warn(`cue: [pause] without a valid number, using ${PAUSE_DEFAULT}s`);
          n = PAUSE_DEFAULT;
        }
        return { kind: "pause", seconds: clamp(n, PAUSE_MIN, PAUSE_MAX) };
      }
      case TAG.sfx: {
        const sfx = args[0];
        return sfx && includes(SFX_NAMES, sfx) ? { kind: "sfx", name: sfx as SfxName } : null;
      }
      case TAG.light: {
        const mode = args[0];
        if (!mode || !includes(LIGHT_MODES, mode)) return null;
        if (mode !== "blackout") return { kind: "light", mode: mode as LightMode };
        let n = parseNumber(args[1]);
        if (n === undefined) {
          this.stats.defaulted++;
          this.warn(`cue: [light blackout] without a valid number, using ${BLACKOUT_DEFAULT}s`);
          n = BLACKOUT_DEFAULT;
        }
        return { kind: "light", mode: "blackout", seconds: clamp(n, BLACKOUT_MIN, BLACKOUT_MAX) };
      }
      case TAG.ambient: {
        const mode = args[0];
        return mode && includes(AMBIENT_MODES, mode) ? { kind: "ambient", mode: mode as AmbientMode } : null;
      }
      case TAG.photo: {
        const [verb, id] = args;
        return verb === PHOTO_VERB && id ? { kind: "photo", id } : null;
      }
      default:
        return null;
    }
  }
}

import type { CueEvent, Style } from "./spec";

export interface SegmentOptions {
  /** Hard limit per segment (adapter.caps.maxChars). */
  maxChars: number;
  /**
   * Soft target: merge consecutive same-style sentences while the merged text
   * stays within this many chars. 0 = never merge (one sentence per segment, Kokoro).
   */
  targetChars: number;
}

type SpeechEvent = Extract<CueEvent, { kind: "speech" }>;

/** Split text into sentences, keeping terminal punctuation. Naive: "Mr." will split. */
export function splitSentences(text: string): string[] {
  const parts = text.match(/[^.!?…]+(?:[.!?…]+["'”’)\]]*|$)/g) ?? [];
  return parts.map((s) => s.trim()).filter((s) => /[\p{L}\p{N}]/u.test(s));
}

/** Break an over-long sentence at commas, then spaces, so no piece exceeds max. */
function hardSplit(text: string, max: number): string[] {
  if (text.length <= max) return [text];
  const out: string[] = [];
  let rest = text;
  while (rest.length > max) {
    const window = rest.slice(0, max);
    let cut = Math.max(window.lastIndexOf(", "), window.lastIndexOf("; "));
    if (cut < max * 0.4) cut = window.lastIndexOf(" ");
    if (cut <= 0) cut = max; // no space at all: cut hard
    else cut += 1;
    out.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) out.push(rest);
  return out;
}

/**
 * Split speech events into sentences and merge adjacent same-style sentences
 * up to targetChars. Non-speech events pass through and act as merge barriers,
 * so a pause or sfx between two sentences is never swallowed.
 */
export function segment(events: CueEvent[], opts: SegmentOptions): CueEvent[] {
  const out: CueEvent[] = [];
  let pending: SpeechEvent | null = null;

  const flush = () => {
    if (pending) out.push(pending);
    pending = null;
  };

  for (const ev of events) {
    if (ev.kind !== "speech") {
      flush();
      out.push(ev);
      continue;
    }
    for (const sentence of splitSentences(ev.text).flatMap((s) => hardSplit(s, opts.maxChars))) {
      const p: SpeechEvent | null = pending;
      if (p && p.style === (ev.style as Style) && p.text.length + 1 + sentence.length <= Math.min(opts.targetChars, opts.maxChars)) {
        p.text += " " + sentence;
      } else {
        flush();
        pending = { kind: "speech", text: sentence, style: ev.style };
      }
    }
  }
  flush();
  return out;
}

import { describe, expect, it, vi } from "vitest";
import { CueParser } from "./parser";
import { segment } from "./segmenter";
import type { CueEvent } from "./spec";

const quiet = () => {};
const parse = (s: string) => CueParser.parse(s, quiet);

describe("every tag", () => {
  it("pause", () => {
    expect(parse("[pause 2.5]").events).toEqual([{ kind: "pause", seconds: 2.5 }]);
  });
  it.each(["whisper", "slow", "trembling", "shout"] as const)("style %s applies to the rest of the line", (s) => {
    expect(parse(`[${s}] hello there`).events).toEqual([{ kind: "speech", text: "hello there", style: s }]);
  });
  it.each(["breath", "sigh", "gasp", "laugh"] as const)("nonverbal %s", (nv) => {
    expect(parse(`[${nv}]`).events).toEqual([{ kind: "nonverbal", nv }]);
  });
  it.each(["creak", "knock", "footsteps", "door", "heartbeat", "static", "drip", "scrape", "whispers"] as const)(
    "sfx %s",
    (name) => {
      expect(parse(`[sfx ${name}]`).events).toEqual([{ kind: "sfx", name }]);
    },
  );
  it("light modes", () => {
    expect(parse("[light flicker]").events).toEqual([{ kind: "light", mode: "flicker" }]);
    expect(parse("[light red]").events).toEqual([{ kind: "light", mode: "red" }]);
    expect(parse("[light pulse]").events).toEqual([{ kind: "light", mode: "pulse" }]);
    expect(parse("[light calm]").events).toEqual([{ kind: "light", mode: "calm" }]);
    expect(parse("[light blackout 3]").events).toEqual([{ kind: "light", mode: "blackout", seconds: 3 }]);
  });
  it("ambient modes", () => {
    for (const mode of ["low", "swell", "stop"] as const) {
      expect(parse(`[ambient ${mode}]`).events).toEqual([{ kind: "ambient", mode }]);
    }
  });
  it("photo reveal", () => {
    expect(parse("[photo reveal room_1]").events).toEqual([{ kind: "photo", id: "room_1" }]);
  });
});

describe("leniency", () => {
  it("is case-insensitive and tolerates extra spaces", () => {
    expect(parse("[  PAUSE   2 ]  [Sfx  CREAK]").events).toEqual([
      { kind: "pause", seconds: 2 },
      { kind: "sfx", name: "creak" },
    ]);
  });
  it("accepts a unit suffix on pause", () => {
    expect(parse("[pause 2s]").events).toEqual([{ kind: "pause", seconds: 2 }]);
  });
  it("drops unknown tags, warns and counts them", () => {
    const warn = vi.fn();
    const { events, stats } = CueParser.parse("[sfx explosion] [dance] [light disco] [photo reveal] Hello.", warn);
    expect(events).toEqual([{ kind: "speech", text: "Hello.", style: "normal" }]);
    expect(stats.unknownTags).toBe(4);
    expect(warn).toHaveBeenCalledTimes(4);
  });
  it("strips (pause 2) and *junk* instead of speaking it", () => {
    const { events, stats } = parse("You wait (pause 2) and *sighs* listen.");
    expect(events).toEqual([
      { kind: "speech", text: "You wait", style: "normal" },
      { kind: "speech", text: "and", style: "normal" },
      { kind: "speech", text: "listen.", style: "normal" },
    ]);
    expect(stats.junkDropped).toBe(2);
  });
  it("keeps ordinary parentheses as speech", () => {
    expect(parse("The door (the old one) creaks.").events).toEqual([
      { kind: "speech", text: "The door (the old one) creaks.", style: "normal" },
    ]);
  });
  it("drops an unterminated tag rather than speaking it", () => {
    const { events, stats } = parse("Listen [pause 2");
    expect(events).toEqual([{ kind: "speech", text: "Listen", style: "normal" }]);
    expect(stats.junkDropped).toBe(1);
  });
  it("lines with only tags produce only events", () => {
    expect(parse("[sfx creak] [light flicker]").events.map((e) => e.kind)).toEqual(["sfx", "light"]);
  });
  it("drops punctuation-only speech", () => {
    expect(parse("[pause 1] ...").events).toEqual([{ kind: "pause", seconds: 1 }]);
  });
});

describe("pause clamping and defaults", () => {
  it("clamps to 0.2-6", () => {
    expect(parse("[pause 0]").events).toEqual([{ kind: "pause", seconds: 0.2 }]);
    expect(parse("[pause 99]").events).toEqual([{ kind: "pause", seconds: 6 }]);
    expect(parse("[pause -3]").events).toEqual([{ kind: "pause", seconds: 0.2 }]);
  });
  it("uses defaults for missing or bad numbers and counts them", () => {
    const a = parse("[pause]");
    expect(a.events).toEqual([{ kind: "pause", seconds: 1 }]);
    expect(a.stats.defaulted).toBe(1);
    expect(parse("[pause abc]").events).toEqual([{ kind: "pause", seconds: 1 }]);
    expect(parse("[light blackout]").events).toEqual([{ kind: "light", mode: "blackout", seconds: 2 }]);
  });
  it("clamps blackout duration", () => {
    expect(parse("[light blackout 60]").events).toEqual([{ kind: "light", mode: "blackout", seconds: 6 }]);
  });
});

describe("style scope", () => {
  it("applies from the tag to the end of the line only", () => {
    const { events } = parse("Before. [whisper] It isn't now.\nNext line.");
    expect(events).toEqual([
      { kind: "speech", text: "Before.", style: "normal" },
      { kind: "speech", text: "It isn't now.", style: "whisper" },
      { kind: "speech", text: "Next line.", style: "normal" },
    ]);
  });
  it("last style wins from that point", () => {
    expect(parse("[slow] [whisper] hello").events).toEqual([{ kind: "speech", text: "hello", style: "whisper" }]);
    expect(parse("[slow] one [shout] two").events).toEqual([
      { kind: "speech", text: "one", style: "slow" },
      { kind: "speech", text: "two", style: "shout" },
    ]);
  });
  it("splits around inline tags", () => {
    expect(parse("The grey coat [pause 0.8] [slow] has one sleeve raised.").events).toEqual([
      { kind: "speech", text: "The grey coat", style: "normal" },
      { kind: "pause", seconds: 0.8 },
      { kind: "speech", text: "has one sleeve raised.", style: "slow" },
    ]);
  });
});

describe("incremental parsing", () => {
  const script = "[ambient low]\nYou hear it. [pause 2]\n[whisper] Closer now.\n[sfx creak] [light flicker]";
  const whole = parse(script).events;

  it("emits events only for completed lines", () => {
    const p = new CueParser(quiet);
    expect(p.push("[ambient low]")).toEqual([]);
    expect(p.push("\n")).toEqual([{ kind: "ambient", mode: "low" }]);
    expect(p.flush()).toEqual([]);
  });
  it("splitting a tag mid-way gives the same result as parsing whole", () => {
    for (let cut = 1; cut < script.length; cut++) {
      const p = new CueParser(quiet);
      const got = [...p.push(script.slice(0, cut)), ...p.push(script.slice(cut)), ...p.flush()];
      expect(got).toEqual(whole);
    }
  });
  it("char-by-char equals whole", () => {
    const p = new CueParser(quiet);
    const got: CueEvent[] = [];
    for (const ch of script) got.push(...p.push(ch));
    got.push(...p.flush());
    expect(got).toEqual(whole);
  });
  it("handles CRLF", () => {
    expect(parse("[ambient low]\r\nHello.\r\n").events).toHaveLength(2);
  });
});

describe("empty input", () => {
  it("yields nothing", () => {
    expect(parse("").events).toEqual([]);
    expect(parse("\n\n   \n").events).toEqual([]);
  });
});

describe("segmenter", () => {
  const sp = (text: string, style: "normal" | "whisper" = "normal"): CueEvent => ({ kind: "speech", text, style });
  const texts = (evs: CueEvent[]) => evs.map((e) => (e.kind === "speech" ? e.text : e.kind));

  it("one sentence per segment when targetChars is 0 (Kokoro)", () => {
    const out = segment([sp("One. Two! Three?")], { maxChars: 500, targetChars: 0 });
    expect(texts(out)).toEqual(["One.", "Two!", "Three?"]);
  });
  it("merges same-style sentences up to the soft target", () => {
    const out = segment([sp("One. Two. Three.")], { maxChars: 500, targetChars: 9 });
    expect(texts(out)).toEqual(["One. Two.", "Three."]);
  });
  it("never merges across a style change or a non-speech event", () => {
    const out = segment([sp("One."), sp("Two.", "whisper"), { kind: "pause", seconds: 1 }, sp("Three.")], {
      maxChars: 500,
      targetChars: 350,
    });
    expect(texts(out)).toEqual(["One.", "Two.", "pause", "Three."]);
  });
  it("hard-splits a sentence longer than maxChars", () => {
    const long = "word ".repeat(40).trim() + ".";
    const out = segment([sp(long)], { maxChars: 50, targetChars: 0 });
    expect(out.length).toBeGreaterThan(1);
    for (const e of out) if (e.kind === "speech") expect(e.text.length).toBeLessThanOrEqual(50);
  });
  it("keeps text without terminal punctuation", () => {
    expect(texts(segment([sp("no full stop")], { maxChars: 500, targetChars: 0 }))).toEqual(["no full stop"]);
  });
});

import type { NonVerbal, Style } from "../../cue/spec";

export type { NonVerbal, Style };

export interface VoiceInfo {
  id: string;
  label: string;
}

export interface TTSAdapter {
  id: "kokoro-web" | "elevenlabs" | "voice-server";
  label: string;
  caps: {
    styles: Set<Style>; // natively supported styles
    nonverbals: Set<NonVerbal>; // natively supported non-verbals
    offline: boolean;
    latency: "low" | "high";
    maxChars: number;
  };
  synth(
    seg: { text: string; style: Style; leadingNonverbal?: NonVerbal; voice: string },
    signal?: AbortSignal,
  ): Promise<AudioBuffer>;
}

// Runs kokoro-js off the main thread. Protocol is defined by the types below.
import { KokoroTTS } from "kokoro-js";

export interface WorkerVoice {
  id: string;
  name: string;
  language: string;
  gender: string;
  grade: string;
}

export type WorkerRequest =
  | { type: "load" }
  | { type: "synth"; id: number; text: string; voice: string; speed: number };

export type WorkerResponse =
  | { type: "progress"; file: string; loaded: number; total: number; status: string }
  | { type: "ready"; device: "webgpu" | "wasm"; dtype: string; voices: WorkerVoice[]; loadMs: number }
  | { type: "audio"; id: number; samples: Float32Array; sampleRate: number; ms: number }
  | { type: "error"; id?: number; message: string };

const MODEL_ID = "onnx-community/Kokoro-82M-v1.0-ONNX";

let tts: KokoroTTS | null = null;
const post = (msg: WorkerResponse, transfer: Transferable[] = []) =>
  (self as unknown as Worker).postMessage(msg, transfer);

async function hasWebGpu(): Promise<boolean> {
  try {
    const gpu = (navigator as unknown as { gpu?: { requestAdapter(): Promise<unknown> } }).gpu;
    return !!gpu && !!(await gpu.requestAdapter());
  } catch {
    return false;
  }
}

async function load() {
  const t0 = performance.now();
  const progress_callback = (p: { status: string; file?: string; loaded?: number; total?: number }) => {
    if (p.file) post({ type: "progress", status: p.status, file: p.file, loaded: p.loaded ?? 0, total: p.total ?? 0 });
  };

  let device: "webgpu" | "wasm" = "wasm";
  let dtype: "fp32" | "q8" = "q8";
  // kokoro-js recommends fp32 on WebGPU; q8 is for WASM.
  if (await hasWebGpu()) {
    try {
      tts = await KokoroTTS.from_pretrained(MODEL_ID, { dtype: "fp32", device: "webgpu", progress_callback });
      device = "webgpu";
      dtype = "fp32";
    } catch (e) {
      console.warn("kokoro: WebGPU load failed, falling back to WASM", e);
    }
  }
  if (!tts) tts = await KokoroTTS.from_pretrained(MODEL_ID, { dtype: "q8", device: "wasm", progress_callback });

  const voices = Object.entries(tts.voices).map(([id, v]) => ({
    id,
    name: v.name,
    language: v.language,
    gender: v.gender,
    grade: v.overallGrade,
  }));
  post({ type: "ready", device, dtype, voices, loadMs: performance.now() - t0 });
}

async function synth(id: number, text: string, voice: string, speed: number) {
  if (!tts) throw new Error("Kokoro is not loaded");
  const t0 = performance.now();
  const audio = await tts.generate(text, { voice: voice as never, speed });
  const samples = audio.audio;
  post({ type: "audio", id, samples, sampleRate: audio.sampling_rate, ms: performance.now() - t0 }, [samples.buffer]);
}

self.onmessage = async (e: MessageEvent<WorkerRequest>) => {
  const msg = e.data;
  try {
    if (msg.type === "load") await load();
    else if (msg.type === "synth") await synth(msg.id, msg.text, msg.voice, msg.speed);
  } catch (err) {
    post({ type: "error", id: msg.type === "synth" ? msg.id : undefined, message: String(err instanceof Error ? err.message : err) });
  }
};

import type { Style, TTSAdapter, VoiceInfo } from "./types";
import type { WorkerRequest, WorkerResponse } from "./kokoro.worker";
import { timing } from "../../lib/timing";

export interface KokoroProgress {
  file: string;
  loaded: number;
  total: number;
}

export interface KokoroStatus {
  device: "webgpu" | "wasm";
  dtype: string;
  loadMs: number;
}

/** Kokoro's `speed` per style. Whisper/trembling/shout are emulated in the audio graph (M2/M5), not here. */
const SPEED: Partial<Record<Style, number>> = { slow: 0.8 };

/** Provisional default; chosen from the voice list by grade, not by ear. Verify by listening. */
export const DEFAULT_KOKORO_VOICE = "bm_george";

export class KokoroWebAdapter implements TTSAdapter {
  readonly id = "kokoro-web" as const;
  readonly label = "Kokoro (in browser)";
  readonly caps = {
    styles: new Set<Style>(["normal", "slow"]),
    nonverbals: new Set<never>(),
    offline: true,
    latency: "low" as const,
    maxChars: 500,
  };

  voices: VoiceInfo[] = [];
  status: KokoroStatus | null = null;

  private worker: Worker | null = null;
  private loading: Promise<void> | null = null;
  private nextId = 1;
  private pending = new Map<number, { resolve: (r: { samples: Float32Array; sampleRate: number }) => void; reject: (e: Error) => void }>();

  constructor(private readonly onProgress?: (p: KokoroProgress) => void) {}

  /** Load the model (idempotent). Downloads weights on first use. */
  load(): Promise<void> {
    if (this.loading) return this.loading;
    this.loading = new Promise<void>((resolve, reject) => {
      const worker = new Worker(new URL("./kokoro.worker.ts", import.meta.url), { type: "module" });
      this.worker = worker;
      worker.onmessage = (e: MessageEvent<WorkerResponse>) => {
        const m = e.data;
        if (m.type === "progress") {
          this.onProgress?.({ file: m.file, loaded: m.loaded, total: m.total });
        } else if (m.type === "ready") {
          this.voices = m.voices.map((v) => ({ id: v.id, label: `${v.name} (${v.language}, ${v.gender}, grade ${v.grade})` }));
          this.status = { device: m.device, dtype: m.dtype, loadMs: m.loadMs };
          timing.record(`kokoro load (${m.device}/${m.dtype})`, m.loadMs);
          resolve();
        } else if (m.type === "audio") {
          timing.record("tts segment", m.ms);
          this.pending.get(m.id)?.resolve({ samples: m.samples, sampleRate: m.sampleRate });
          this.pending.delete(m.id);
        } else if (m.type === "error") {
          const err = new Error(m.message);
          if (m.id === undefined) {
            this.loading = null; // allow retry
            reject(err);
          } else {
            this.pending.get(m.id)?.reject(err);
            this.pending.delete(m.id);
          }
        }
      };
      worker.onerror = (e) => {
        this.loading = null;
        reject(new Error(e.message || "Kokoro worker failed to start"));
      };
      worker.postMessage({ type: "load" } satisfies WorkerRequest);
    });
    return this.loading;
  }

  async synth(
    seg: { text: string; style: Style; voice: string },
    signal?: AbortSignal,
  ): Promise<AudioBuffer> {
    await this.load();
    if (signal?.aborted) throw new DOMException("aborted", "AbortError");
    const id = this.nextId++;
    const result = new Promise<{ samples: Float32Array; sampleRate: number }>((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
    });
    signal?.addEventListener("abort", () => {
      this.pending.get(id)?.reject(new DOMException("aborted", "AbortError"));
      this.pending.delete(id);
    });
    this.worker!.postMessage({
      type: "synth",
      id,
      text: seg.text,
      voice: seg.voice,
      speed: SPEED[seg.style] ?? 1,
    } satisfies WorkerRequest);
    const { samples, sampleRate } = await result;
    const buf = new AudioBuffer({ length: samples.length, sampleRate, numberOfChannels: 1 });
    buf.copyToChannel(samples as Float32Array<ArrayBuffer>, 0);
    return buf;
  }
}

// M1 minimal playback: prerender speech, then play it back-to-back with pauses as silence.
// Replaced/extended by the full timeline + audio graph in M2.
import type { CueEvent } from "../cue/spec";
import type { TTSAdapter } from "../adapters/tts/types";
import { timing } from "../lib/timing";

export interface PlayOptions {
  adapter: TTSAdapter;
  voice: string;
  ctx: AudioContext;
  signal?: AbortSignal;
  onPrerender?: (done: number, total: number) => void;
  onLine?: (text: string) => void;
}

export async function playSimple(events: CueEvent[], o: PlayOptions): Promise<void> {
  const speech = events.filter((e): e is Extract<CueEvent, { kind: "speech" }> => e.kind === "speech");
  const buffers = new Map<CueEvent, AudioBuffer>();

  const stopPrerender = timing.start("prerender total");
  o.onPrerender?.(0, speech.length);
  for (const ev of speech) {
    buffers.set(ev, await o.adapter.synth({ text: ev.text, style: ev.style, voice: o.voice }, o.signal));
    o.onPrerender?.(buffers.size, speech.length);
  }
  stopPrerender();

  if (o.ctx.state === "suspended") await o.ctx.resume();
  const sources: AudioBufferSourceNode[] = [];
  const timers: number[] = [];
  let cursor = o.ctx.currentTime + 0.3;
  const t0 = cursor;

  for (const ev of events) {
    if (ev.kind === "pause") {
      cursor += ev.seconds;
    } else if (ev.kind === "speech") {
      const buf = buffers.get(ev)!;
      const src = o.ctx.createBufferSource();
      src.buffer = buf;
      src.connect(o.ctx.destination);
      src.start(cursor);
      sources.push(src);
      timers.push(window.setTimeout(() => o.onLine?.(ev.text), (cursor - o.ctx.currentTime) * 1000));
      cursor += buf.duration;
    }
    // other event kinds are timeline-only; they are ignored until M2
  }

  await new Promise<void>((resolve) => {
    const end = window.setTimeout(resolve, (cursor - o.ctx.currentTime) * 1000 + 200);
    o.signal?.addEventListener("abort", () => {
      clearTimeout(end);
      timers.forEach(clearTimeout);
      sources.forEach((s) => {
        try {
          s.stop();
        } catch {
          /* not started */
        }
      });
      resolve();
    });
  });
  timing.record("play duration", (cursor - t0) * 1000);
}

import { useSyncExternalStore } from "react";
import { timing } from "../lib/timing";

export function DebugPanel() {
  useSyncExternalStore(timing.subscribe, timing.version);
  const entries = timing.entries();
  const counters = [...timing.counters()];

  return (
    <dl className="debug">
      {counters.map(([k, v]) => (
        <div key={k}>
          <dt>{k}</dt>
          <dd>{v}</dd>
        </div>
      ))}
      {entries.map((e, i) => (
        <div key={i}>
          <dt>{e.label}</dt>
          <dd>{Math.round(e.ms)} ms</dd>
        </div>
      ))}
      {!entries.length && !counters.length && <dd>No timings yet.</dd>}
    </dl>
  );
}

import { useMemo, useRef, useState } from "react";
import { CueParser } from "../cue/parser";
import { segment } from "../cue/segmenter";
import { DEFAULT_KOKORO_VOICE, KokoroWebAdapter, type KokoroProgress } from "../adapters/tts/kokoroWeb";
import type { VoiceInfo } from "../adapters/tts/types";
import { playSimple } from "../engine/player";
import { timing } from "../lib/timing";
import { DebugPanel } from "./DebugPanel";

type DrawerTab = "settings" | "memories" | "debug";
type Phase = "idle" | "loading" | "summoning" | "playing";

export function App() {
  const [level, setLevel] = useState(3);
  const [tab, setTab] = useState<DrawerTab>("settings");
  const [phase, setPhase] = useState<Phase>("idle");
  const [progress, setProgress] = useState<KokoroProgress | null>(null);
  const [prerender, setPrerender] = useState<[number, number] | null>(null);
  const [line, setLine] = useState("");
  const [voices, setVoices] = useState<VoiceInfo[]>([]);
  const [voice, setVoice] = useState(DEFAULT_KOKORO_VOICE);
  const [error, setError] = useState("");
  const [device, setDevice] = useState("");

  const abort = useRef<AbortController | null>(null);
  const ctx = useRef<AudioContext | null>(null);
  const adapter = useMemo(() => new KokoroWebAdapter(setProgress), []);

  async function loadModel() {
    setError("");
    setPhase("loading");
    try {
      await adapter.load();
      setVoices(adapter.voices);
      if (adapter.status) setDevice(`${adapter.status.device}/${adapter.status.dtype}`);
    } catch (e) {
      setError(String(e instanceof Error ? e.message : e));
    }
    setPhase("idle");
  }

  async function playSample() {
    setError("");
    setLine("");
    ctx.current ??= new AudioContext();
    const ac = new AbortController();
    abort.current = ac;
    try {
      setPhase("loading");
      await adapter.load();
      setVoices(adapter.voices);
      if (adapter.status) setDevice(`${adapter.status.device}/${adapter.status.dtype}`);

      const res = await fetch(`${import.meta.env.BASE_URL}sample/sample.cue.txt`);
      if (!res.ok) throw new Error(`Could not load the sample script (${res.status})`);
      const { events, stats } = CueParser.parse(await res.text());
      if (stats.unknownTags) timing.count("unknown tags dropped", stats.unknownTags);
      const segments = segment(events, { maxChars: adapter.caps.maxChars, targetChars: 0 });

      setPhase("summoning");
      await playSimple(segments, {
        adapter,
        voice,
        ctx: ctx.current,
        signal: ac.signal,
        onPrerender: (d, t) => setPrerender([d, t]),
        onLine: setLine,
      });
    } catch (e) {
      if (!(e instanceof DOMException && e.name === "AbortError")) setError(String(e instanceof Error ? e.message : e));
    }
    setPrerender(null);
    setPhase("idle");
  }

  const busy = phase !== "idle";
  const pct = progress && progress.total ? Math.round((progress.loaded / progress.total) * 100) : null;

  return (
    <div className="shell">
      <header className="topbar">
        <h1>Localghost</h1>
        <div className="dial">
          <span>Scare</span>
          <input type="range" min={1} max={5} value={level} onChange={(e) => setLevel(Number(e.target.value))} />
          <span>{level}</span>
        </div>
        <span className="spacer" />
        <span className="badge">Data flow: —</span>
      </header>
      <div className="body">
        <main className="stage">
          {phase === "idle" && !line && <div className="hint">The Stage. Nothing is summoned yet.</div>}
          {phase === "loading" && (
            <div className="hint">
              Loading voice model{pct !== null ? ` — ${pct}%` : "…"}
              {progress ? <div>{progress.file}</div> : null}
            </div>
          )}
          {phase === "summoning" && prerender && (
            <div className="hint">
              Summoning… {prerender[0]}/{prerender[1]}
            </div>
          )}
          {line && <div className="line">{line}</div>}
          {error && <div className="hint" style={{ color: "var(--alarm)" }}>{error}</div>}
          <div>
            {phase === "idle" ? (
              <button className="primary" onClick={playSample}>
                Play sample
              </button>
            ) : (
              <button onClick={() => abort.current?.abort()}>Stop</button>
            )}
          </div>
        </main>
        <aside className="drawer">
          <div className="tabs">
            {(["settings", "memories", "debug"] as const).map((t) => (
              <button key={t} className={tab === t ? "active" : ""} onClick={() => setTab(t)}>
                {t}
              </button>
            ))}
          </div>
          <div className="panel">
            {tab === "settings" && (
              <>
                <label>
                  Voice (Kokoro)
                  <select value={voice} onChange={(e) => setVoice(e.target.value)} disabled={busy}>
                    {!voices.length && <option value={voice}>{voice} (load model to list voices)</option>}
                    {voices.map((v) => (
                      <option key={v.id} value={v.id}>
                        {v.label}
                      </option>
                    ))}
                  </select>
                </label>
                <button onClick={loadModel} disabled={busy}>
                  Load voice model
                </button>
                {device && <div className="badge">Running on {device}</div>}
              </>
            )}
            {tab === "memories" && <div className="hint">Coming in M4.</div>}
            {tab === "debug" && <DebugPanel />}
          </div>
        </aside>
      </div>
    </div>
  );
}

