export type ContentPart =
  | { type: "text"; text: string }
  | { type: "image_url"; image_url: { url: string } };

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string | ContentPart[];
}

export interface ChatRequest {
  messages: ChatMessage[];
  temperature?: number;
  maxTokens?: number;
  json?: boolean;
}

export interface LLMAdapter {
  id: string;
  caps: { vision: boolean; streaming: boolean; local: boolean };
  chat(req: ChatRequest, signal?: AbortSignal): AsyncIterable<string>;
}

export interface LLMConfig {
  baseUrl: string;
  model: string;
  /** Sent as a Bearer token only when set, and only to baseUrl. */
  apiKey?: string;
}

/** An error with a human-friendly explanation and optional copyable fix commands. */
export class LLMError extends Error {
  constructor(
    message: string,
    readonly commands: { label: string; command: string }[] = [],
  ) {
    super(message);
    this.name = "LLMError";
  }
}

export interface LLMPreset {
  id: "ollama" | "lmstudio" | "llamacpp" | "custom";
  label: string;
  baseUrl: string;
}

export const LLM_PRESETS: readonly LLMPreset[] = [
  { id: "ollama", label: "Ollama", baseUrl: "http://localhost:11434/v1" },
  { id: "lmstudio", label: "LM Studio", baseUrl: "http://localhost:1234/v1" },
  { id: "llamacpp", label: "llama.cpp server", baseUrl: "http://localhost:8080/v1" },
  { id: "custom", label: "Custom (OpenAI-compatible)", baseUrl: "" },
];

/**
 * Left empty on purpose: the exact Gemma 4 tag must be confirmed with `ollama list`, not guessed
 * (PLAN.md, M3). Set it once confirmed.
 */
export const DEFAULT_MODEL = "";

import { SseParser } from "../../lib/sse";
import { LLMError, type ChatRequest, type LLMAdapter, type LLMConfig } from "./types";

const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]", "::1"]);

export function hostOf(baseUrl: string): string {
  try {
    return new URL(baseUrl).hostname;
  } catch {
    return baseUrl;
  }
}

export function isLocalUrl(baseUrl: string): boolean {
  return LOCAL_HOSTS.has(hostOf(baseUrl));
}

const trimSlash = (s: string) => s.trim().replace(/\/+$/, "");

export class OpenAICompatAdapter implements LLMAdapter {
  readonly id = "openai-compat";
  readonly caps: LLMAdapter["caps"];

  constructor(private readonly cfg: LLMConfig) {
    // vision support can't be known up front; assume yes and let the vision pass report failure (M4)
    this.caps = { vision: true, streaming: true, local: isLocalUrl(cfg.baseUrl) };
  }

  private headers(): Record<string, string> {
    const h: Record<string, string> = { "Content-Type": "application/json" };
    if (this.cfg.apiKey) h.Authorization = `Bearer ${this.cfg.apiKey}`;
    return h;
  }

  private unreachable(): LLMError {
    const host = hostOf(this.cfg.baseUrl);
    if (this.caps.local) {
      const origin = typeof location !== "undefined" ? location.origin : "http://localhost:5173";
      return new LLMError(
        `Could not reach ${host}. Is Ollama (or your local server) running? Did you set OLLAMA_ORIGINS to include ${origin} and restart Ollama?`,
        [
          { label: "Windows (PowerShell), then restart Ollama", command: `setx OLLAMA_ORIGINS "${origin}"` },
          { label: "macOS / Linux", command: `OLLAMA_ORIGINS=${origin} ollama serve` },
        ],
      );
    }
    return new LLMError(`Could not reach ${host}. Check the URL, your network, and that the server allows requests from this page (CORS).`);
  }

  async listModels(signal?: AbortSignal): Promise<string[]> {
    let res: Response;
    try {
      res = await fetch(`${trimSlash(this.cfg.baseUrl)}/models`, { headers: this.headers(), signal });
    } catch (e) {
      if (signal?.aborted) throw e;
      throw this.unreachable();
    }
    if (!res.ok) throw new LLMError(`Listing models failed (${res.status}).`);
    const body = (await res.json()) as { data?: { id?: string }[] };
    return (body.data ?? []).map((m) => m.id).filter((id): id is string => !!id);
  }

  async *chat(req: ChatRequest, signal?: AbortSignal): AsyncGenerator<string> {
    if (!this.cfg.model.trim()) {
      throw new LLMError("No model name set. Enter the model tag from `ollama list` in Settings.");
    }
    const body: Record<string, unknown> = {
      model: this.cfg.model,
      messages: req.messages,
      stream: true,
      temperature: req.temperature,
      max_tokens: req.maxTokens,
    };
    if (req.json) body.response_format = { type: "json_object" };

    let res: Response;
    try {
      res = await fetch(`${trimSlash(this.cfg.baseUrl)}/chat/completions`, {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(body),
        signal,
      });
    } catch (e) {
      if (signal?.aborted) throw e;
      throw this.unreachable();
    }
    if (!res.ok) {
      const detail = (await res.text().catch(() => "")).slice(0, 300);
      throw new LLMError(`The model server returned ${res.status}${detail ? `: ${detail}` : ""}`);
    }
    if (!res.body) throw new LLMError("The model server sent no response body.");

    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    const sse = new SseParser();

    const deltas = function* (data: string[]) {
      for (const d of data) {
        try {
          const text = (JSON.parse(d) as { choices?: { delta?: { content?: string } }[] }).choices?.[0]?.delta?.content;
          if (text) yield text;
        } catch {
          /* ignore a malformed event */
        }
      }
    };

    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      const r = sse.push(decoder.decode(value, { stream: true }));
      yield* deltas(r.data);
      if (r.done) return;
    }
    yield* deltas(sse.flush().data);
  }
}

import type { LightMode } from "../cue/spec";

export interface ScareProfile {
  level: 1 | 2 | 3 | 4 | 5;
  name: string;
  words: readonly [number, number];
  jumps: number;
  /** Max [sfx]/[light] tags in total. */
  budget: number;
  /** [light] modes the director may use (cumulative ladder; ADR-017). */
  lights: readonly LightMode[];
  ending: string;
  ceiling: string;
}

export const PROFILES: readonly ScareProfile[] = [
  { level: 1, name: "Campfire", words: [350, 450], jumps: 0, budget: 3, lights: ["pulse", "calm"], ending: "warm, resolved", ceiling: "eerie only" },
  { level: 2, name: "Uneasy", words: [400, 550], jumps: 1, budget: 5, lights: ["flicker", "pulse", "calm"], ending: "ambiguous", ceiling: "eerie, no violence" },
  { level: 3, name: "Haunted", words: [450, 650], jumps: 2, budget: 8, lights: ["flicker", "blackout", "pulse", "calm"], ending: "ambiguous", ceiling: "implied threat" },
  { level: 4, name: "Dread", words: [550, 750], jumps: 3, budget: 12, lights: ["flicker", "blackout", "red", "pulse", "calm"], ending: "bleak", ceiling: "implied violence, no gore" },
  { level: 5, name: "Nightmare", words: [600, 800], jumps: 4, budget: 16, lights: ["flicker", "blackout", "red", "pulse", "calm"], ending: "twist: it's in your room now", ceiling: "implied violence, no graphic gore" },
];

export function profileFor(level: number): ScareProfile {
  return PROFILES[Math.min(5, Math.max(1, Math.round(level))) - 1];
}

import { AMBIENT_MODES, NONVERBALS, PHOTO_VERB, SFX_NAMES, STYLES, TAG, type LightMode } from "../cue/spec";
import type { ScareProfile } from "./profiles";

export const USER_MESSAGE = "Begin.";
export const REPAIR_LINE = "Your previous output broke the format. Output only the cue script.";

export interface PromptInput {
  profile: ScareProfile;
  /** JSON string of the vision inventories (M4). */
  inventory?: string;
  notes?: string;
  /** Photo id to reveal at the climax, when photos exist (M4). */
  bestPhotoId?: string;
}

const lightArg = (m: LightMode) => (m === "blackout" ? "blackout N" : m);

/** Tag reference generated from cue/spec.ts so the prompt can never drift from the parser. */
function tagReference(p: ScareProfile): string {
  return [
    [`[${TAG.pause} N]`, ...STYLES.map((s) => `[${s}]`), ...NONVERBALS.map((n) => `[${n}]`)].join(" "),
    `[${TAG.sfx} ${SFX_NAMES.join("|")}]`,
    `[${TAG.light} ${p.lights.map(lightArg).join("|")}] [${TAG.ambient} ${AMBIENT_MODES.join("|")}]`,
  ]
    .map((l) => `   ${l}`)
    .join("\n");
}

/** The style example must only use tags this level allows, or small models will copy the violation. */
function example(p: ScareProfile): string {
  const flicker = p.lights.includes("flicker") ? `[${TAG.light} flicker]` : `[${TAG.light} pulse]`;
  const blackout = p.lights.includes("blackout") ? `[${TAG.light} blackout 3]` : `[${TAG.light} calm]`;
  return [
    `[${TAG.ambient} low]`,
    "You told yourself the hallway light was off when you left.",
    `[${TAG.pause} 1.5]`,
    "[whisper] It isn't now.",
    `[${TAG.sfx} creak] ${flicker}`,
    `[${TAG.pause} 3]`,
    `The grey coat on your door [${TAG.pause} 0.8] [slow] has one sleeve raised.`,
    `[gasp] ${blackout}`,
  ].join("\n");
}

export function buildSystemPrompt(i: PromptInput): string {
  const p = i.profile;
  const photoRule = i.bestPhotoId
    ? `Use [${TAG.photo} ${PHOTO_VERB} ${i.bestPhotoId}] exactly once, at the climax.`
    : `Do not use [${TAG.photo} ${PHOTO_VERB}].`;

  return `You write and direct short horror audio dramas that are performed aloud to one listener in a dark room.

LISTENER'S PLACE (from their own photos):
${i.inventory?.trim() || "No photos. Invent an ordinary modern home."}

LISTENER'S NOTES:
${i.notes?.trim() || "None."}

SCARE LEVEL ${p.level} — ${p.name}:
- Length: ${p.words[0]}–${p.words[1]} words of spoken text.
- Jump scares: ${p.jumps}. Build slowly; earn each one with silence first.
- Effects budget: at most ${p.budget} [sfx]/[light] tags in total.
- Ending: ${p.ending}.
- Content limits: ${p.ceiling}. Never sexual content, never harm to children, never self-harm.

WRITING RULES:
1. Second person, present tense ("You hear..."). Written for the ear: short sentences, rhythm, repetition.
2. Set it in the listener's place. Use at least 3 concrete objects from the inventory, by name, where they are.
3. Output ONLY the cue script. One beat per line. No title, no markdown, no notes, no explanations.
4. Use ONLY these tags, exactly as written:
${tagReference(p)}
   ${photoRule}
5. Silence is your strongest tool. Use [${TAG.pause}] generously before reveals.
6. Start with [${TAG.ambient} low]. End with [${TAG.pause} 3] then [${TAG.ambient} stop].
7. Never mention AI, models, photos, or that this is a story.

EXAMPLE STYLE (do not reuse its content):
${example(p)}`;
}

import { CueParser, type ParserStats } from "../cue/parser";
import type { CueEvent } from "../cue/spec";
import type { ChatMessage, LLMAdapter } from "../adapters/llm/types";
import { timing } from "../lib/timing";
import { profileFor } from "./profiles";
import { buildSystemPrompt, REPAIR_LINE, USER_MESSAGE, type PromptInput } from "./prompts";

export const TEMPERATURE = 0.9;
/** ~800 words of speech plus tags fits well under this; it only guards against runaway generation. */
export const MAX_TOKENS = 2048;
export const MIN_SPEECH_WORDS = 10;

export interface DirectorOptions extends Omit<PromptInput, "profile"> {
  adapter: LLMAdapter;
  level: number;
  signal?: AbortSignal;
  /** Raw streamed text, for the live "Summoning" display. */
  onText?(delta: string): void;
}

export interface DirectorResult {
  events: CueEvent[];
  text: string;
  stats: ParserStats;
  attempts: number;
  /** true if the final output still failed the format check */
  degraded: boolean;
  ttftMs: number | null;
  genMs: number;
  tokensPerSec: number;
}

interface Attempt {
  events: CueEvent[];
  text: string;
  stats: ParserStats;
  ttftMs: number | null;
  genMs: number;
  chunks: number;
}

export const countSpeechWords = (events: CueEvent[]) =>
  events.reduce((n, e) => (e.kind === "speech" ? n + e.text.split(/\s+/).filter(Boolean).length : n), 0);

export const tagCount = (events: CueEvent[]) => events.filter((e) => e.kind !== "speech").length;

/** The repair trigger from PLAN.md: fewer than 10 speech words, or no tags at all. */
export const isBroken = (events: CueEvent[]) => countSpeechWords(events) < MIN_SPEECH_WORDS || tagCount(events) === 0;

async function attempt(adapter: LLMAdapter, messages: ChatMessage[], o: DirectorOptions): Promise<Attempt> {
  const parser = new CueParser();
  const events: CueEvent[] = [];
  let text = "";
  let chunks = 0;
  let ttftMs: number | null = null;
  const t0 = performance.now();

  for await (const delta of adapter.chat({ messages, temperature: TEMPERATURE, maxTokens: MAX_TOKENS }, o.signal)) {
    if (ttftMs === null) ttftMs = performance.now() - t0;
    chunks++;
    text += delta;
    o.onText?.(delta);
    events.push(...parser.push(delta));
  }
  events.push(...parser.flush());
  return { events, text, stats: parser.stats, ttftMs, genMs: performance.now() - t0, chunks };
}

/** Stream a story from the LLM, parse it incrementally, and retry once if the format is broken. */
export async function direct(o: DirectorOptions): Promise<DirectorResult> {
  const system = buildSystemPrompt({
    profile: profileFor(o.level),
    inventory: o.inventory,
    notes: o.notes,
    bestPhotoId: o.bestPhotoId,
  });
  const messages = (user: string): ChatMessage[] => [
    { role: "system", content: system },
    { role: "user", content: user },
  ];

  let best = await attempt(o.adapter, messages(USER_MESSAGE), o);
  let attempts = 1;

  if (isBroken(best.events)) {
    console.warn("director: output broke the format, retrying once");
    o.onText?.("\n");
    const retry = await attempt(o.adapter, messages(`${USER_MESSAGE}\n\n${REPAIR_LINE}`), o);
    attempts = 2;
    // "If it still fails, play what we have": keep whichever attempt has more speech
    if (!isBroken(retry.events) || countSpeechWords(retry.events) > countSpeechWords(best.events)) best = retry;
  }

  const tokensPerSec = best.genMs > 0 ? best.chunks / (best.genMs / 1000) : 0;
  if (best.ttftMs !== null) timing.record("llm time-to-first-token", best.ttftMs);
  timing.record("llm generation", best.genMs);
  timing.note(`llm: ~${tokensPerSec.toFixed(1)} tokens/s (stream chunks), ${attempts} attempt(s)`);
  if (best.stats.unknownTags) timing.count("unknown tags dropped", best.stats.unknownTags);

  return {
    events: best.events,
    text: best.text,
    stats: best.stats,
    attempts,
    degraded: isBroken(best.events),
    ttftMs: best.ttftMs,
    genMs: best.genMs,
    tokensPerSec,
  };
}

import { describe, expect, it, vi } from "vitest";
import { OpenAICompatAdapter } from "../adapters/llm/openaiCompat";
import { LLMError, type ChatRequest, type LLMAdapter } from "../adapters/llm/types";
import { SFX_NAMES } from "../cue/spec";
import { direct, isBroken } from "./director";
import { PROFILES, profileFor } from "./profiles";
import { buildSystemPrompt, REPAIR_LINE } from "./prompts";

const GOOD = "[ambient low]\nYou hear the old hallway breathing around you tonight.\n[pause 2]\n[sfx creak]\n[ambient stop]\n";

function fakeAdapter(outputs: string[]): LLMAdapter & { calls: ChatRequest[] } {
  const calls: ChatRequest[] = [];
  return {
    id: "fake",
    caps: { vision: false, streaming: true, local: true },
    calls,
    async *chat(req) {
      calls.push(req);
      const out = outputs[Math.min(calls.length - 1, outputs.length - 1)];
      for (let i = 0; i < out.length; i += 7) yield out.slice(i, i + 7); // awkward chunk boundaries
    },
  };
}

describe("director", () => {
  it("streams, parses incrementally and does not retry good output", async () => {
    const a = fakeAdapter([GOOD]);
    const seen: string[] = [];
    const r = await direct({ adapter: a, level: 3, onText: (d) => seen.push(d) });
    expect(a.calls).toHaveLength(1);
    expect(r.attempts).toBe(1);
    expect(r.degraded).toBe(false);
    expect(seen.join("")).toBe(GOOD);
    expect(r.events.map((e) => e.kind)).toEqual(["ambient", "speech", "pause", "sfx", "ambient"]);
  });

  it("retries once with the repair line when there are no tags", async () => {
    const a = fakeAdapter(["Just a plain paragraph with no tags at all but plenty of words in it.", GOOD]);
    const r = await direct({ adapter: a, level: 3 });
    expect(a.calls).toHaveLength(2);
    const retryUser = a.calls[1].messages[1].content as string;
    expect(retryUser).toContain(REPAIR_LINE);
    expect(r.attempts).toBe(2);
    expect(r.degraded).toBe(false);
  });

  it("plays what it has if the retry also fails, and never retries twice", async () => {
    const a = fakeAdapter(["nope", "still nope"]);
    const r = await direct({ adapter: a, level: 3 });
    expect(a.calls).toHaveLength(2);
    expect(r.degraded).toBe(true);
  });

  it("isBroken: <10 speech words or no tags", () => {
    expect(isBroken([])).toBe(true);
    expect(isBroken([{ kind: "pause", seconds: 1 }])).toBe(true);
    expect(isBroken([{ kind: "speech", text: "one two three four five six seven eight nine ten", style: "normal" }])).toBe(true);
  });
});

describe("prompts", () => {
  it("only offers light modes the level allows, in both the tag list and the example", () => {
    const p1 = buildSystemPrompt({ profile: profileFor(1) });
    expect(p1).toContain("[light pulse|calm]");
    expect(p1).not.toMatch(/flicker|blackout|red/);
    const p3 = buildSystemPrompt({ profile: profileFor(3) });
    expect(p3).toContain("[light flicker|blackout N|pulse|calm]");
    expect(p3).not.toContain("|red");
  });
  it("lists every sfx from the spec", () => {
    const p = buildSystemPrompt({ profile: profileFor(3) });
    expect(p).toContain(`[sfx ${SFX_NAMES.join("|")}]`);
  });
  it("photo rule depends on whether a photo exists", () => {
    expect(buildSystemPrompt({ profile: profileFor(3) })).toContain("Do not use [photo reveal].");
    expect(buildSystemPrompt({ profile: profileFor(3), bestPhotoId: "room_2" })).toContain(
      "Use [photo reveal room_2] exactly once, at the climax.",
    );
  });
  it("fills inventory, notes and fallbacks", () => {
    const empty = buildSystemPrompt({ profile: profileFor(2) });
    expect(empty).toContain("No photos. Invent an ordinary modern home.");
    expect(empty).toContain("LISTENER'S NOTES:\nNone.");
    const full = buildSystemPrompt({ profile: profileFor(2), inventory: '{"place":"hall"}', notes: "cat named Moss" });
    expect(full).toContain('{"place":"hall"}');
