    expect(PROFILES.map((p) => p.jumps)).toEqual([0, 1, 2, 3, 4]);
    expect(buildSystemPrompt({ profile: profileFor(5) })).toContain("Length: 600–800 words");
  });
});

describe("OpenAICompatAdapter", () => {
  const sse = (...chunks: string[]) =>
    chunks.map((c) => `data: ${JSON.stringify({ choices: [{ delta: { content: c } }] })}\n\n`).join("") + "data: [DONE]\n\n";

  async function collect(it: AsyncIterable<string>) {
    let s = "";
    for await (const d of it) s += d;
    return s;
  }

  it("streams deltas, sends bearer only when a key is set, and image parts pass through", async () => {
    const fetchMock = vi.fn(async () => new Response(sse("Hel", "lo"), { status: 200 }));
    vi.stubGlobal("fetch", fetchMock);
    const a = new OpenAICompatAdapter({ baseUrl: "http://localhost:11434/v1/", model: "m" });
    const img = { type: "image_url" as const, image_url: { url: "data:image/jpeg;base64,AAA" } };
    expect(await collect(a.chat({ messages: [{ role: "user", content: [img] }], json: true }))).toBe("Hello");
    const [url, init] = fetchMock.mock.calls[0] as unknown as [string, RequestInit];
    expect(url).toBe("http://localhost:11434/v1/chat/completions");
    expect((init.headers as Record<string, string>).Authorization).toBeUndefined();
    const body = JSON.parse(init.body as string);
    expect(body.stream).toBe(true);
    expect(body.response_format).toEqual({ type: "json_object" });
    expect(body.messages[0].content[0]).toEqual(img);

    const keyed = new OpenAICompatAdapter({ baseUrl: "https://api.example.com/v1", model: "m", apiKey: "k" });
    await collect(keyed.chat({ messages: [] }));
    const init2 = fetchMock.mock.calls[1][1] as unknown as RequestInit;
    expect((init2.headers as Record<string, string>).Authorization).toBe("Bearer k");
    vi.unstubAllGlobals();
  });

  it("detects local hosts", () => {
    const c = (u: string) => new OpenAICompatAdapter({ baseUrl: u, model: "m" }).caps.local;
    expect(c("http://localhost:11434/v1")).toBe(true);
    expect(c("http://127.0.0.1:1234/v1")).toBe(true);
    expect(c("http://[::1]:8080/v1")).toBe(true);
    expect(c("https://api.example.com/v1")).toBe(false);
  });

  it("explains a refused connection with the OLLAMA_ORIGINS fix", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => Promise.reject(new TypeError("Failed to fetch"))));
    const a = new OpenAICompatAdapter({ baseUrl: "http://localhost:11434/v1", model: "m" });
    const err = await collect(a.chat({ messages: [] })).catch((e) => e);
    expect(err).toBeInstanceOf(LLMError);
    expect(err.message).toContain("OLLAMA_ORIGINS");
    expect(err.commands.length).toBeGreaterThan(0);
    vi.unstubAllGlobals();
  });

  it("requires a model name", async () => {
    const a = new OpenAICompatAdapter({ baseUrl: "http://localhost:11434/v1", model: " " });
    await expect(collect(a.chat({ messages: [] }))).rejects.toThrow(/model name/i);
  });

  it("reports HTTP errors with status and detail", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => new Response("model not found", { status: 404 })));
    const a = new OpenAICompatAdapter({ baseUrl: "http://localhost:11434/v1", model: "x" });
    await expect(collect(a.chat({ messages: [] }))).rejects.toThrow(/404.*model not found/);
    vi.unstubAllGlobals();
  });
});

// LLM settings persisted in localStorage. The API key lives here and is only ever sent to baseUrl.
import { DEFAULT_MODEL, LLM_PRESETS, type LLMPreset } from "../adapters/llm/presets";

export interface LLMSettings {
  preset: LLMPreset["id"];
  baseUrl: string;
  model: string;
  apiKey: string;
}

const KEY = "llmSettings";

export const DEFAULT_LLM_SETTINGS: LLMSettings = {
  preset: "ollama",
  baseUrl: LLM_PRESETS[0].baseUrl,
  model: DEFAULT_MODEL,
  apiKey: "",
};

export function loadLLMSettings(): LLMSettings {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) return { ...DEFAULT_LLM_SETTINGS, ...(JSON.parse(raw) as Partial<LLMSettings>) };
  } catch {
    /* storage unavailable or corrupt: fall back to defaults */
  }
  return DEFAULT_LLM_SETTINGS;
}

export function saveLLMSettings(s: LLMSettings) {
  try {
    localStorage.setItem(KEY, JSON.stringify(s));
  } catch {
    /* storage unavailable */
  }
}

import { useState } from "react";
import { LLM_PRESETS } from "../adapters/llm/presets";
import { OpenAICompatAdapter } from "../adapters/llm/openaiCompat";
import type { VoiceInfo } from "../adapters/tts/types";
import type { LLMSettings } from "./settings";
import { ErrorView } from "./ErrorView";

export interface SettingsPanelProps {
  llm: LLMSettings;
  onLlm(s: LLMSettings): void;
  voices: VoiceInfo[];
  voice: string;
  onVoice(v: string): void;
  device: string;
  locked: boolean;
  onLoadVoiceModel(): void;
  reduceFlashing: boolean;
  onReduceFlashing(on: boolean): void;
}

export function SettingsPanel(p: SettingsPanelProps) {
  const [models, setModels] = useState<string[]>([]);
  const [fetching, setFetching] = useState(false);
  const [err, setErr] = useState<unknown>(null);

  async function fetchModels() {
    setErr(null);
    setFetching(true);
    try {
      setModels(await new OpenAICompatAdapter(p.llm).listModels());
    } catch (e) {
      setErr(e);
    }
    setFetching(false);
  }

  const set = (patch: Partial<LLMSettings>) => p.onLlm({ ...p.llm, ...patch });

  return (
    <>
      <h3>Story model</h3>
      <label>
        Provider
        <select
          value={p.llm.preset}
          onChange={(e) => {
            const preset = LLM_PRESETS.find((x) => x.id === e.target.value)!;
            set({ preset: preset.id, baseUrl: preset.id === "custom" ? p.llm.baseUrl : preset.baseUrl });
          }}
        >
          {LLM_PRESETS.map((x) => (
            <option key={x.id} value={x.id}>
              {x.label}
            </option>
          ))}
        </select>
      </label>
      <label>
        Base URL
        <input value={p.llm.baseUrl} onChange={(e) => set({ preset: "custom", baseUrl: e.target.value })} />
      </label>
      <label>
        Model
        <input
          list="llm-models"
          placeholder="tag from `ollama list`"
          value={p.llm.model}
          onChange={(e) => set({ model: e.target.value })}
        />
        <datalist id="llm-models">
          {models.map((m) => (
            <option key={m} value={m} />
          ))}
        </datalist>
      </label>
      <button onClick={fetchModels} disabled={fetching || !p.llm.baseUrl}>
        {fetching ? "Fetching…" : "Fetch models"}
      </button>
      {models.length > 0 && <div className="badge">{models.length} model(s) found</div>}
      <label>
        API key (optional, only sent to the URL above)
        <input type="password" autoComplete="off" value={p.llm.apiKey} onChange={(e) => set({ apiKey: e.target.value })} />
      </label>
      {err != null && <ErrorView error={err} />}

      <h3>Voice</h3>
      <label>
        Voice (Kokoro)
        <select value={p.voice} onChange={(e) => p.onVoice(e.target.value)} disabled={p.locked}>
          {!p.voices.length && <option value={p.voice}>{p.voice} (load model to list voices)</option>}
          {p.voices.map((v) => (
            <option key={v.id} value={v.id}>
              {v.label}
            </option>
          ))}
        </select>
      </label>
      <button onClick={p.onLoadVoiceModel} disabled={p.locked}>
        Load voice model
      </button>
      {p.device && <div className="badge">Running on {p.device}</div>}

      <h3>Accessibility</h3>
      <label className="check">
        <input type="checkbox" checked={p.reduceFlashing} onChange={(e) => p.onReduceFlashing(e.target.checked)} />
        Reduce flashing
      </label>
    </>
  );
}

import { LLMError } from "../adapters/llm/types";

/** Shows an error message, plus copyable fix commands for LLMError. */
export function ErrorView({ error }: { error: unknown }) {
  const message = error instanceof Error ? error.message : String(error);
  const commands = error instanceof LLMError ? error.commands : [];
  return (
    <div className="error">
      <div>{message}</div>
      {commands.map((c) => (
        <div key={c.command} className="cmd">
          <small>{c.label}</small>
          <code>{c.command}</code>
          <button onClick={() => void navigator.clipboard?.writeText(c.command)}>Copy</button>
        </div>
      ))}
    </div>
  );
}

