41	  const [error, setError] = useState("");
42	  const [device, setDevice] = useState("");
43	  const [reduceFlashing, setReduceFlashing] = useState(() => readFlag("reduceFlashing"));
44	  const [showNotice, setShowNotice] = useState(false);
45	  const [hasStory, setHasStory] = useState(false);
46	
47	  const fxBlack = useRef<HTMLDivElement>(null);
48	  const fxRed = useRef<HTMLDivElement>(null);
49	  const fxVignette = useRef<HTMLDivElement>(null);
50	  const effects = useRef<Effects | null>(null);
51	  const reduceRef = useRef(reduceFlashing);
52	  reduceRef.current = reduceFlashing;
53	
54	  const abort = useRef<AbortController | null>(null);
55	  const player = useRef<Player | null>(null);
56	  const prepared = useRef<Prepared | null>(null);
57	  const preparedVoice = useRef<string | null>(null);
58	  const [hudVisible, setHudVisible] = useState(true);
59	  const lineN = useRef(0);
60	  const adapter = useMemo(() => new KokoroWebAdapter(setProgress), []);
61	  useEffect(() => () => adapter.dispose(), [adapter]);
62	
63	  useEffect(() => {
64	    if (fxBlack.current && fxRed.current && fxVignette.current) {
65	      effects.current = new Effects(
66	        { black: fxBlack.current, red: fxRed.current, vignette: fxVignette.current },
67	        () => reduceRef.current,
68	      );
69	    }
70	  }, []);
71	
72	  const getPlayer = () => (player.current ??= new Player(new AudioContext()));
73	
74	  const run = useCallback(async (p: Prepared) => {
75	    effects.current?.clear();
76	    await getPlayer().start(p, {
77	      onLine: (text, style) => setLine({ text, style, n: ++lineN.current }),
78	      onVisual: (ev, at) => {
79	        if (ev.kind === "light") effects.current?.trigger(ev.mode, ev.seconds, at);
80	      },
81	      onFrame: (t) => effects.current?.update(t),
82	      onEnd: () => {
83	        effects.current?.clear();
84	        setPlayerState("idle");
