87	    setPlayerState("playing");
88	  }, []);
89	
90	  async function ensureModel() {
91	    await adapter.load();
92	    setVoices(adapter.voices);
93	    if (adapter.status) setDevice(`${adapter.status.device}/${adapter.status.dtype}`);
94	  }
95	
96	  async function playSample() {
97	    setError("");
98	    setLine(null);
99	    const ac = new AbortController();
100	    abort.current = ac;
101	    try {
102	      getPlayer(); // create the AudioContext inside the user gesture
103	      if (prepared.current && preparedVoice.current === voice) {
104	        await run(prepared.current); // same script + voice: reuse the synthesis (M5 adds the real cache)
105	        return;
106	      }
107	      setPhase("loading");
108	      await ensureModel();
109	
110	      const res = await fetch(`${import.meta.env.BASE_URL}sample/sample.cue.txt`);
111	      if (!res.ok) throw new Error(`Could not load the sample script (${res.status})`);
112	      const { events, stats } = CueParser.parse(await res.text());
113	      if (stats.unknownTags) timing.count("unknown tags dropped", stats.unknownTags);
