115	
116	      setPhase("summoning");
117	      const p = await prepare(segments, {
118	        adapter,
119	        voice,
120	        signal: ac.signal,
121	        onProgress: (d, t) => setPrerender([d, t]),
122	      });
123	      prepared.current = p;
124	      preparedVoice.current = voice;
125	      setHasStory(true);
126	      setPhase("idle");
127	      setPrerender(null);
128	      await run(p);
129	    } catch (e) {
130	      if (!(e instanceof DOMException && e.name === "AbortError")) setError(String(e instanceof Error ? e.message : e));
131	      setPhase("idle");
132	      setPrerender(null);
133	    }
134	  }
135	
136	  async function loadModel() {
137	    setError("");
138	    setPhase("loading");
139	    try {
140	      await ensureModel();
141	    } catch (e) {
142	      setError(String(e instanceof Error ? e.message : e));
143	    }
