147	  const requestPlay = () => {
148	    if (readFlag("photosensitivityAck")) void playSample();
149	    else setShowNotice(true);
150	  };
151	
152	  const replay = () => {
153	    if (prepared.current) {
154	      setLine(null);
155	      void run(prepared.current);
156	    }
157	  };
158	
159	  const stop = () => {
160	    abort.current?.abort();
161	    player.current?.stop();
162	    setPlayerState("idle");
163	  };
164	
165	  const playerRef = player;
166	  const stopRef = useRef(stop);
167	  stopRef.current = stop;
168	
169	  const toggle = useCallback(async () => {
170	    const p = player.current;
171	    if (!p) return;
172	    await p.toggle();
173	    setPlayerState(p.state);
174	  }, []);
175	
176	  // Space toggles pause (unless typing in a field)
177	  useEffect(() => {
178	    const ignore = (e: KeyboardEvent) =>
179	      e.code !== "Space" || /^(INPUT|SELECT|TEXTAREA)$/.test((e.target as HTMLElement)?.tagName ?? "");
180	    const down = (e: KeyboardEvent) => {
181	      if (e.code === "Escape" && playerRef.current && playerRef.current.state !== "idle") {
