183	        return;
184	      }
185	      if (ignore(e)) return;
186	      e.preventDefault();
187	      if (!e.repeat) void toggle();
188	    };
189	    const up = (e: KeyboardEvent) => {
190	      if (!ignore(e)) e.preventDefault(); // stop a focused button from also "clicking"
191	    };
192	    window.addEventListener("keydown", down);
193	    window.addEventListener("keyup", up);
194	    return () => {
195	      window.removeEventListener("keydown", down);
196	      window.removeEventListener("keyup", up);
197	    };
198	  }, [toggle]);
199	
200	  const busy = phase !== "idle";
201	  const active = playerState !== "idle";
202	
203	  // While a story plays, the HUD fades after 3 s of inactivity and returns on mouse move / key press.
204	  useEffect(() => {
205	    if (!active) {
206	      setHudVisible(true);
207	      return;
208	    }
209	    let t = window.setTimeout(() => setHudVisible(false), 3000);
