238	
239	  const controls = showNotice ? (
240	    <div className="notice">
241	      <p>
242	        <strong>Photosensitivity notice.</strong> This experience uses flickering lights, blackouts and red flashes. Turn on
243	        "Reduce flashing" to replace them with slow dims.
244	      </p>
245	      <button
246	        className="primary"
247	        onClick={() => {
248	          writeFlag("photosensitivityAck", true);
249	          setShowNotice(false);
250	          void playSample();
251	        }}
252	      >
253	        I understand, begin
254	      </button>{" "}
255	      <button
256	        onClick={() => {
257	          setReduceFlashing(true);
258	          writeFlag("reduceFlashing", true);
259	        }}
260	      >
261	        Reduce flashing{reduceFlashing ? " ✓" : ""}
262	      </button>
263	    </div>
264	  ) : busy ? (
265	    <button onClick={stop}>Stop</button>
266	  ) : active ? null : (
267	    <>
268	      <button className="primary" onClick={requestPlay}>
269	        Play sample
270	      </button>{" "}
271	      {hasStory && <button onClick={replay}>Replay</button>}
272	    </>
273	  );
274	
275	  return (
276	    <div className={`shell ${active ? "immersive" : ""}`}>
277	      <header className="topbar">
278	        <h1>Localghost</h1>
279	        <div className="dial">
280	          <span>Scare</span>
281	          <input type="range" min={1} max={5} value={level} onChange={(e) => setLevel(Number(e.target.value))} />
282	          <span>{level}</span>
283	        </div>
284	        <span className="spacer" />
285	        <span className="badge">Data flow: —</span>
286	      </header>
287	      <div className="body">
288	        <Stage
289	          fxBlack={fxBlack}
290	          fxRed={fxRed}
291	          fxVignette={fxVignette}
292	          line={line}
293	          hint={hint}
294	          error={error}
295	          controls={controls}
296	          playerState={playerState}
297	        />
298	        {active && (
299	          <div className={`hud ${hudVisible ? "" : "faded"}`}>
300	            <button aria-label={playerState === "paused" ? "Resume" : "Pause"} onClick={() => void toggle()}>
301	              {playerState === "paused" ? "▶" : "❚❚"}
302	            </button>
303	            <button aria-label="Stop" onClick={stop}>
304	              ■
305	            </button>
306	          </div>
307	        )}
308	        <aside className="drawer">
309	          <div className="tabs">
310	            {(["settings", "memories", "debug"] as const).map((t) => (
311	              <button key={t} className={tab === t ? "active" : ""} onClick={() => setTab(t)}>
312	                {t}
313	              </button>
314	            ))}
315	          </div>
316	          <div className="panel">
317	            {tab === "settings" && (
318	              <>
319	                <label>
320	                  Voice (Kokoro)
321	                  <select value={voice} onChange={(e) => setVoice(e.target.value)} disabled={busy || active}>
322	                    {!voices.length && <option value={voice}>{voice} (load model to list voices)</option>}
323	                    {voices.map((v) => (
324	                      <option key={v.id} value={v.id}>
325	                        {v.label}
326	                      </option>
327	                    ))}
328	                  </select>
329	                </label>
330	                <button onClick={loadModel} disabled={busy || active}>
331	                  Load voice model
332	                </button>
333	                {device && <div className="badge">Running on {device}</div>}
334	                <label className="check">
335	                  <input
336	                    type="checkbox"
337	                    checked={reduceFlashing}
338	                    onChange={(e) => {
339	                      setReduceFlashing(e.target.checked);
340	                      writeFlag("reduceFlashing", e.target.checked);
341	                    }}
342	                  />
343	                  Reduce flashing
344	                </label>
345	              </>
346	            )}
347	            {tab === "memories" && <div className="hint">Coming in M4.</div>}
348	            {tab === "debug" && <DebugPanel />}
349	          </div>
350	        </aside>
351	      </div>
352	    </div>
353	  );
354	}
